def occurance(ch,t,n):
    nb=0
    for i in range(n) : 
        if t[i]["num"]==ch:
            nb+=1
    return nb 

def verif_alpha(ch):
    i = 0
    while i < len(ch) and (ch[i].upper() in ["A", "Z"] ):
        i += 1
    return i == len(ch)

